def can_partition(arr):
    s = sum(arr)
    if s % 2 != 0:
        return False
    target = s // 2
    dp = [False] * (target + 1)
    dp[0] = True
    for n in arr:
        for i in range(target, n - 1, -1):
            dp[i] = dp[i] or dp[i - n]
    return dp[target]

