def max_sum_subarray(a, k):
    n = len(a)
    if n < k:
        return None
    current_sum = sum(a[:k])
    max_sum = current_sum
    for i in range(k, n):
        current_sum += a[i] - a[i - k]
        if current_sum > max_sum:
            max_sum = current_sum
    return max_sum

